var corruptedDurabilityLoss    = 0.2;
var combatantDurabilityLoss    = 0.01;
var nonCombatantDurabilityLoss = 0.1;
var caravanDurabilityLoss      = 0.01;
var nodeSiegeDurabilityLoss    = 0.01;
var guildWarDurabilityLoss     = 0.01;
var nodeWarDurabilityLoss      = 0.01;


const isCorrupted = HasAlignment(GetOwner(), $#6221802054776738159:6064629443752951818$);
const isCombatant = HasAlignment(GetOwner(), $#6221802054776738159:6064629443707731976$);
const isInCaravanEvent = 
   HasAlignment(GetOwner(), $#6221802054776738159:6064629443694362626$)      // Caravan Defender
|| HasAlignment(GetOwner(), $#6221802054776738159:6064629443693772801$);     // Caravan Attacker
const isInNodeSiegeEvent = 
HasAlignment(GetOwner(), $#6221802054776738159:6064632733143662592$)    // Siege Attacker
|| HasAlignment(GetOwner(), $#6221802054776738159:6064632733144580097$); // Siege Defender
const isInGuildWarEvent = 
HasAlignment(GetOwner(), $#6221802054776738159:6064630610806636544$)     // Guild War Attacker
|| HasAlignment(GetOwner(), $#6221802054776738159:6064631086261600301$);  // Guild War Defender
const isInNodeWarEvent = 
HasAlignment(GetOwner(), $#6221802054776738159:6064631086252163116$)      // Node War Attacker
|| HasAlignment(GetOwner(), $#6221802054776738159:6064631051909070850$);   // Node War Defender

// Starting durability loss mod is non-combatant
var flaggingDurabilityMod = nonCombatantDurabilityLoss;

// combatant
if(isCombatant)
{
   set flaggingDurabilityMod = combatantDurabilityLoss;
}
// caravan event
if(isInCaravanEvent)
{
    set flaggingDurabilityMod = caravanDurabilityLoss;
}
// siege event
if(isInNodeSiegeEvent)
{
    set flaggingDurabilityMod = nodeSiegeDurabilityLoss;
}
// guild war event
if(isInGuildWarEvent)
{
    set flaggingDurabilityMod = guildWarDurabilityLoss;
}
// node war event
if(isInNodeWarEvent)
{
    set flaggingDurabilityMod = nodeWarDurabilityLoss;
}
// corrupted
if(isCorrupted)
{
   set flaggingDurabilityMod =  corruptedDurabilityLoss;
}

//const durabilityLoss = GetItemMaxDurability() * SelectFloat(isInPvPEvent, 0.0, SelectFloat(isCorrupted, 0.1, SelectFloat(isFlagged, 0.01, 0.1)));
var durabilityLoss = GetItemMaxDurability() * flaggingDurabilityMod;

//SelectFloat(durabilityLoss < 1.0, 1.0, durabilityLoss)
if(durabilityLoss < 1.0)
{
   set durabilityLoss = 1.0;
}
durabilityLoss

