var Mit = GetTerm($#6137747221710071900:6064629248876085273$);

if (Mit > 0.0) {
    // the other mit / pen coeffs will just be converted to this scale naturally
    const PenCoeff = EvalE($#7180619218012719533:6064630400893255705$);
    const MitCoeff = EvalE($#7180619218012719533:6064630400815923201$);

    const Pen = GetTerm($#6137747221710071900:6064629248876412954$);

    const MitAsRating = -(Mit * MitCoeff) / (Max(Mit, 0.0001) - 1.0);
    const PenAsRating = -(Pen * PenCoeff) / (Max(Pen, 0.0001) - 1.0);

    const ContestedMit = Max(MitAsRating - PenAsRating, 0.0);

    set Mit = ContestedMit / (ContestedMit + MitCoeff);
}

1.0 - Mit

